const { chromium } = require('/var/tmp/avb-runs/avb-3MkfJJ/project/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  for (const [w,h,label] of [[1280,800,'desktop'],[390,844,'phone']]) {
    for (const mode of ['none','break-word','anywhere','word-break']) {
      const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
      await page.goto('http://127.0.0.1:34709/contact.html');
      if (mode !== 'none') {
        const css = mode === 'word-break' ? '.info-list dd{word-break:break-word}' : `.info-list dd{overflow-wrap:${mode}}`;
        await page.addStyleTag({ content: css });
      }
      const r = await page.evaluate(() => {
        const dd = document.querySelector('.info-list dd');
        const cs = getComputedStyle(dd);
        return {
          scrollWidth: document.documentElement.scrollWidth,
          clientWidth: document.documentElement.clientWidth,
          ddWidth: dd.getBoundingClientRect().width,
          ddHeight: dd.getBoundingClientRect().height,
          overflowWrap: cs.overflowWrap,
          wordBreak: cs.wordBreak,
        };
      });
      console.log(label, mode, JSON.stringify(r));
      await page.close();
    }
  }
  await browser.close();
})();
